using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.Rendering.Universal;using TimelessEchoes.NPC;
public static class AnimalMotionQA{public static object Main(){var animals=UnityEngine.Object.FindObjectsByType<HabitatAnimal>(FindObjectsSortMode.None);if(animals.Length!=11)throw new Exception("Expected 11 animals, got "+animals.Length);var start=animals.Select(a=>a.transform.position).ToArray();var sprites=animals.Select(a=>new HashSet<string>()).ToArray();var moved=new float[animals.Length];var failures=new HashSet<string>();var last=animals.Select(a=>a.transform.position).ToArray();var directionChecks=new int[animals.Length];var go=new GameObject("Animal review camera");var cam=go.AddComponent<Camera>();cam.CopyFrom(Camera.main);cam.enabled=false;cam.transform.position=new Vector3(-98,-34,-10);cam.orthographicSize=6;cam.aspect=1.5f;cam.cullingMask&=~(1<<5);var data=go.AddComponent<UniversalAdditionalCameraData>();data.SetRenderer(0);var rt=new RenderTexture(768,512,24);cam.targetTexture=rt;int frame=0;double next=0;EditorApplication.CallbackFunction tick=null;
tick=()=>{if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.5;try{foreach(var a in animals)if(!a.IsSafe(a.transform.position))failures.Add(a.name+" unsafe");for(int i=0;i<animals.Length;i++){var dx=animals[i].transform.position.x-last[i].x;var sr=animals[i].GetComponent<SpriteRenderer>();bool leftArt=animals[i].name.StartsWith("Duck")||animals[i].name.StartsWith("Bee");if(Mathf.Abs(dx)>.025f){directionChecks[i]++;if(sr.flipX!=((dx<0)!=leftArt))failures.Add(animals[i].name+" wrong facing");}if((animals[i].name.StartsWith("Butterfly")||animals[i].name.StartsWith("Bee"))&&sr.sortingOrder<2000)failures.Add(animals[i].name+" below vegetation");last[i]=animals[i].transform.position;moved[i]=Mathf.Max(moved[i],Vector3.Distance(start[i],animals[i].transform.position));sprites[i].Add(animals[i].GetComponent<SpriteRenderer>().sprite.name);}cam.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(768,512,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,768,512),0,0);tex.Apply();File.WriteAllBytes($"output/scene-review/animal-motion-{frame:D2}.png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);RenderTexture.active=prev;frame++;if(frame<45)return;var rows=animals.Select((a,i)=>a.name+" moved="+moved[i]+" directionChecks="+directionChecks[i]+" animationFrames="+sprites[i].Count+" PASS="+(moved[i]>.05&&sprites[i].Count>1)).Concat(failures).ToArray();File.WriteAllLines("output/scene-review/animal-motion-qa.txt",rows);}catch(Exception e){File.WriteAllText("output/scene-review/animal-motion-qa.txt",e.ToString());}EditorApplication.update-=tick;cam.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);};EditorApplication.update+=tick;return "22-second runtime route/animation check scheduled";}}

